import{_ as a,o as l,c as t,a8 as i}from"./chunks/framework.DQoZbSQ3.js";const c=JSON.parse('{"title":"文献综述哪家强：Claude、DeepSeek、Kimi、GLM 还是 GPT？","description":"","frontmatter":{"title":"文献综述哪家强：Claude、DeepSeek、Kimi、GLM 还是 GPT？","date":"2026-05-18T00:00:00.000Z","category":"AI知识","tags":["模型横评","Claude","DeepSeek","Kimi","GPT","文献综述","AI工作流"]},"headers":[],"relativePath":"ai-knowledge/literature-review-model-comparison.md","filePath":"ai-knowledge/literature-review-model-comparison.md","lastUpdated":1779075337000}'),r={name:"ai-knowledge/literature-review-model-comparison.md"};function o(d,e,s,n,u,p){return l(),t("div",null,[...e[0]||(e[0]=[i('<blockquote><p>本文转载自微信公众号，<a href="https://mp.weixin.qq.com/s/EjSuXl2UhJy_V8UgdlswEg" target="_blank" rel="noreferrer">点击查看原文</a>，原文观点仅代表作者个人意见。</p></blockquote><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>作者花时间实测了五款顶级大模型完成同一个任务：写一篇关于社会偏好（Social Preferences）的中文文献综述，自带 BibTeX，能跑出 PDF。然后用 Zotero 本地库 + CrossRef + OpenAlex，把五份稿子里一千多条引用逐一核查。</p><p>测试模型：Claude Opus 4.7、DeepSeek V4 Pro、GPT-5.5、GLM-5.1、Kimi K2.6</p><h2 id="核心结论" tabindex="-1">核心结论 <a class="header-anchor" href="#核心结论" aria-label="Permalink to &quot;核心结论&quot;">​</a></h2><p>五家模型分成两档：</p><p><strong>第一档（深度 × 可靠性双优）</strong>：Claude 和 DeepSeek <strong>第二档（各有短板）</strong>：GPT 保守、GLM 和 Kimi 幻觉多</p><hr><h2 id="各模型详细表现" tabindex="-1">各模型详细表现 <a class="header-anchor" href="#各模型详细表现" aria-label="Permalink to &quot;各模型详细表现&quot;">​</a></h2><h3 id="claude-opus-4-7-—-最扎实-但有翻译腔" tabindex="-1">Claude Opus 4.7 — 最扎实，但有翻译腔 <a class="header-anchor" href="#claude-opus-4-7-—-最扎实-但有翻译腔" aria-label="Permalink to &quot;Claude Opus 4.7 — 最扎实，但有翻译腔&quot;">​</a></h3><ul><li>27 页、约 13000 字、104 条文献</li><li><strong>104 条引用全部可核查，0 条幻觉，DOI 抽检全过</strong></li><li>理论谱系铺得最完整，公式符号一致，逻辑严密</li><li>短板：中文表达翻译腔最重，长句套长句，读起来像英文综述直译</li></ul><h3 id="deepseek-v4-pro-—-最新-中文更顺" tabindex="-1">DeepSeek V4 Pro — 最新，中文更顺 <a class="header-anchor" href="#deepseek-v4-pro-—-最新-中文更顺" aria-label="Permalink to &quot;DeepSeek V4 Pro — 最新，中文更顺&quot;">​</a></h3><ul><li>约 20000 字、92 条文献，文献追到 2025 年最新工作</li><li><strong>仅 1 条漏网错误引用</strong>，整体可靠性极高</li><li>中文表达比 Claude 自然，读起来更流畅</li><li>适合需要覆盖最新进展的场景</li></ul><h3 id="gpt-5-5-—-最干净-但篇幅不足" tabindex="-1">GPT-5.5 — 最干净，但篇幅不足 <a class="header-anchor" href="#gpt-5-5-—-最干净-但篇幅不足" aria-label="Permalink to &quot;GPT-5.5 — 最干净，但篇幅不足&quot;">​</a></h3><ul><li>50 条文献、0 条幻觉、9000 字</li><li>宁可不写也不编，甚至主动发现并修正了引用里的期刊名错误</li><li>短板：篇幅只有 Claude 的七成，2020 年后重要方向几乎未涉及</li><li>适合写短摘要或用来把关引文清单，不适合直接当完整综述</li></ul><h3 id="glm-5-1-—-最长-幻觉最多" tabindex="-1">GLM-5.1 — 最长，幻觉最多 <a class="header-anchor" href="#glm-5-1-—-最长-幻觉最多" aria-label="Permalink to &quot;GLM-5.1 — 最长，幻觉最多&quot;">​</a></h3><ul><li>134 条引用、15 条幻觉、30000 字</li><li>典型问题：编造文献后正文多次引用，甚至出现与乳腺癌论文混淆的引用</li><li>134 条里有 49 条正文根本未出现，纯凑数</li><li>引用格式风格中途漂移，像多人拼凑未统稿</li></ul><h3 id="kimi-k2-6-—-幻觉最隐蔽" tabindex="-1">Kimi K2.6 — 幻觉最隐蔽 <a class="header-anchor" href="#kimi-k2-6-—-幻觉最隐蔽" aria-label="Permalink to &quot;Kimi K2.6 — 幻觉最隐蔽&quot;">​</a></h3><ul><li>82 条引用、14 条幻觉，错误密度 17%</li><li>特点：DOI 看起来都是真的，但 DOI 指向的真实文献与标题、作者完全不符</li><li>比纯编造更难发现，必须拉元数据反查才能识破</li></ul><hr><h2 id="工作流比模型更重要" tabindex="-1">工作流比模型更重要 <a class="header-anchor" href="#工作流比模型更重要" aria-label="Permalink to &quot;工作流比模型更重要&quot;">​</a></h2><p>这次实验最关键的发现：降低幻觉率不靠模型本身，靠三件事：</p><p><strong>1. 联网工具调用</strong>：Claude 写社会偏好综述调用了 200 多次外部 API，GLM 同样任务不到 30 次，差距就在这里。</p><p><strong>2. 多智能体隔离</strong>：写作智能体和核查智能体分开，让另一个智能体审稿，效果远比模型自查好。同一份草稿让 Kimi 自查只剩 5 条幻觉，独立审阅智能体审出 14 条。</p><p><strong>3. 多阶段流水线</strong>：草稿 → 引用核查 → 修订，把&quot;出引用&quot;和&quot;验引用&quot;切成两步。</p><p>日常使用三步就够：</p><ul><li>要求每条文献必须带 DOI，没有 DOI 的删除</li><li>用 CrossRef 或 OpenAlex 反查 DOI 对应的真实标题，相似度低于 0.6 标红</li><li>标红条目扔回模型要求重写或删除</li></ul><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>推荐</th></tr></thead><tbody><tr><td>直接可用的中等长度综述</td><td>Claude（再让 DeepSeek 改一遍中文）</td></tr><tr><td>长篇覆盖、能接受手工核查</td><td>DeepSeek，或 GLM 配核查脚本</td></tr><tr><td>短摘要、零容忍引用错误</td><td>GPT</td></tr></tbody></table><p><strong>最稳组合</strong>：Claude 写骨架 + DeepSeek 或 GPT 改中文。前者负责理论深度和引用真实性，后者负责去掉翻译腔。</p><hr><h2 id="🐼-熊猫算力视角" tabindex="-1">🐼 熊猫算力视角 <a class="header-anchor" href="#🐼-熊猫算力视角" aria-label="Permalink to &quot;🐼 熊猫算力视角&quot;">​</a></h2><blockquote><p>以下为熊猫算力平台基于实际运营经验的补充说明。</p></blockquote><p>这篇测评有一句话值得反复琢磨：</p><blockquote><p><strong>模型之间的差距比想象中小，工作流之间的差距比想象中大。</strong></p></blockquote><p>工具都趋近于成熟，最终还得落回使用的人会不会编排使用它们。Claude 和 Kimi 在通用基准上分数差不多，但配上联网核查、多智能体审阅之后，差距能拉出一倍——这说明模型能力只是上限，工作流设计才是实际产出的决定因素。</p><p>对熊猫算力的用户来说，这意味着：</p><div class="tip custom-block"><p class="custom-block-title">实操建议</p><ul><li><strong>不要裸调模型直接要结果</strong>，加一步&quot;让另一个模型审一遍&quot;，可靠性立刻上一个台阶</li><li><strong>Claude 的优势在严谨性</strong>，不在视觉创意。需要逻辑严密、引用可靠的场景（学术写作、合同分析、技术文档），Claude 是首选</li><li><strong>组合用模型</strong>比单押一家更划算。熊猫算力支持多模型统一调用，Claude 写、DeepSeek 润色，两次调用成本远低于反复返工的时间成本</li><li>平台上所有模型均按量计费，价格大幅低于官方直连，具体查看<a href="/docs/faq/personal/">计费说明</a></li></ul></div>',38)])])}const m=a(r,[["render",o]]);export{c as __pageData,m as default};
